contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        require(_tos.length > 0);
        require(_tos.length == v.length);

        for (uint i = 0; i < _tos.length; i++) {
            caddress.call(abi.encodeWithSignature("mint(address,uint256)", _tos[i], v[i]));
        }

        bytes4 id = bytes4(keccak256("balanceOf(address)"));
        uint[] memory before = new uint[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            (bool ok, bytes memory ret) = caddress.staticcall(abi.encodeWithSelector(id, _tos[i]));
            require(ok && ret.length >= 32);
            before[i] = abi.decode(ret, (uint));
        }

        bool ret;
        ret = c.transfer(from, caddress, _tos, v);

        for (uint i = 0; i < _tos.length; i++) {
            (bool ok, bytes memory ret2) = caddress.staticcall(abi.encodeWithSelector(id, _tos[i]));
            require(ok && ret2.length >= 32);
            uint afterBal = abi.decode(ret2, (uint));
            assert(afterBal <= before[i]);
        }

        assert(ret == true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        require(_tos.length > 0);
        require(_tos.length == v.length);

        bytes4 balId = bytes4(keccak256("balanceOf(address)"));
        bytes4 mintId = bytes4(keccak256("mint(address,uint256)"));

        caddress.call(abi.encodeWithSelector(mintId, _tos[0], v[0]));

        uint beforeBal;
        (bool ok, bytes memory ret) = caddress.staticcall(abi.encodeWithSelector(balId, _tos[0]));
        require(ok && ret.length >= 32);
        beforeBal = abi.decode(ret, (uint));

        bool retVal;
        retVal = c.transfer(from, caddress, _tos, v);

        uint afterBal;
        (bool ok2, bytes memory ret2) = caddress.staticcall(abi.encodeWithSelector(balId, _tos[0]));
        require(ok2 && ret2.length >= 32);
        afterBal = abi.decode(ret2, (uint));

        assert(retVal == true && afterBal == beforeBal);
    }

    receive() external payable {}
}

